// === Tab: mySketch ===
// for @sableRaphs birds nest streaming backgrounds <3
// influenced by Ahmads https://openprocessing.org/sketch/2319478

const NUM_SHAPES = 350;
const PAD_SHAPES = 15;
let circs, brushes, conns;

function mouseClicked() {
	if (mouseButton === LEFT) setup();
}

function setup() {
  // createCanvas((S = max(windowWidth, windowHeight) * 0.95), S);
  createCanvas(windowWidth * 0.95, windowHeight * 0.95);
	describe("circle packing of different sizes and colors, nearbies are connected with grey lines, some rotating and some with multiple arms")
	S = max(width, height);
	pixelDensity(1);
	background(0, 0, 0);
  colorMode(HSB, 100);
  strokeWeight(3);
	loop();

	// brushes / colors
  silverBrush = new Brush(-1, color("silver"));
  brushes = Brush.genBrushes(~~random(3, 7), ~~random(1, 4));

	// circles
  circs = [];
  const NUM_SIZE_SEG = 10;
  const MAX_RAD = S / 6;
  for (let i = 0; i < NUM_SHAPES; i++) {
    for (let tries = 0; tries < 100; tries++) {
      const r = random();
      const rad = (max(1, ~~(r * NUM_SIZE_SEG)) / NUM_SIZE_SEG) * MAX_RAD;
      // const rad = ~~random(S / 20, S / 5);
      const pos = createVector(
        ~~random(rad + PAD_SHAPES, width - rad - PAD_SHAPES),
        ~~random(rad + PAD_SHAPES, height - rad - PAD_SHAPES)
      );
      const circ = new Circ(pos, rad, random(brushes), ~~(r * NUM_SIZE_SEG));
      if (!circ.overlaps(circs, PAD_SHAPES)) {
        circs.push(circ);
        if (rad <= MAX_RAD / NUM_SIZE_SEG + 0.001) circ.br = silverBrush;
        // console.log(circ);
        break;
      }
    }
  }

	// connections
  conns = [];
  const CONN_DIST = (MAX_RAD / NUM_SIZE_SEG + PAD_SHAPES) * 3;
  for (let i = 0; i < circs.length - 1; i++) {
    for (let j = i + 1; j < circs.length; j++) {
      const c1 = circs[i];
      const c2 = circs[j];
      if (dist(c1.pos.x, c1.pos.y, c2.pos.x, c2.pos.y) < CONN_DIST) {
        conns.push({ c1, c2, br: silverBrush });
      }
    }
  }
}

function draw() {
  background(0, 0, 0);
  fill(65, 100, 10);
	stroke(silverBrush.clr);
  rect(PAD_SHAPES/2, PAD_SHAPES/2, width-PAD_SHAPES, height-PAD_SHAPES, 10);

  for (let c of circs) {
    c.draw();
  }

  for (let c of conns) {
    stroke(c.br.getAlphaClr(50));
    line(c.c1.pos.x, c.c1.pos.y, c.c2.pos.x, c.c2.pos.y);
  }

	// // noLoop() removed for animation
}


// Classes

class Circ {
  constructor(pos, rad, br, dsh = 0) {
    this.pos = pos.copy();
    this.rad = rad;
    this.br = br; // brush
    this.dash = dsh; //  || ~~random(4, rad / PI / 2);
    // number of arms and starting angle
		this.rotA = random(TWO_PI);
		this.rotS = random(-0.2, 0.2);
    this.arms = random() < 0.5 ? 0 : ~~random(5, 17);
    this.arma = random(TWO_PI);
  }

  overlaps(others, pad = 0) {
    for (let o of others) {
      if (
        dist(this.pos.x, this.pos.y, o.pos.x, o.pos.y) <
        this.rad + o.rad + pad
      ) {
        return true;
      }
    }
    return false;
  }

  draw() {
    push();
    translate(this.pos.x, this.pos.y);
		rotate(this.rotA += this.rotS);
		point(0, 0);
		stroke(this.br.clr);
    noFill();
    drawingContext.setLineDash([this.dash]);

    circle(0, 0, this.rad * 2);

    if (this.arms) {
      rotate(this.arma);
      for (let i = 0; i < this.arms; i++) {
        line(0, this.rad, 0, this.rad * 1.2);
        rotate(TWO_PI / this.arms) + random(-0.1, 0.1);
      }
    }

    pop();
  }
}

class Brush {
  constructor(_id, _clr) {
    this.id = _id;
    this.clr = _clr;
  }

  static genBrushes(num = 3, del = 0) {
    const startHue = ~~random(100);
    const deltaHue = ~~(100 / (num + del));
    const hsbSat = ~~random(65, 85);
    const hsbBrt = ~~random(45, 75);

    const res = [];
    for (let i = 0; i < num + del; i++) {
      const brush = new Brush(
        i,
        color((startHue + i * deltaHue) % 100, hsbSat, hsbBrt)
      );
      res.push(brush);
    }
    if (del > 0) {
      res.splice(0, del);
    }

    return res;
  }

	getAlphaClr(a = 25) {
		const clr = this.clr;
		clr.setAlpha(a);
		return clr;
	}
}
